import os, zipfile, math, statistics
from copy import deepcopy
from openpyxl import load_workbook
from openpyxl.utils import get_column_letter
from lxml import etree

IN_PATH = '/root/data/workbook.xlsx'
OUT_PATH = '/root/output/result.xlsx'

TASK_SHEET = 'Task'
DATA_SHEET = 'Data'

# Target blocks
LOOKUP_BLOCKS = [
    (12, 17),
    (19, 24),
    (26, 31),
]
GAP_START_ROW = 35  # 35-40
STATS_ROWS = list(range(42, 48))  # 42-47
WEIGHTED_ROW = 50

COLS = ['H','I','J','K','L']

NS_MAIN = 'http://schemas.openxmlformats.org/spreadsheetml/2006/main'
NS_REL = 'http://schemas.openxmlformats.org/officeDocument/2006/relationships'


def detect_year_header_row(ws, cols=('H','I','J','K','L'), years=(2019,2020,2021,2022,2023), max_scan=50):
    """Find a row where the given columns match the year sequence."""
    for r in range(1, max_scan+1):
        vals = [ws[f'{c}{r}'].value for c in cols]
        if tuple(vals) == tuple(years):
            return r
    return None


def percentile_inc(values, k):
    # Excel PERCENTILE (aka PERCENTILE.INC) with linear interpolation.
    xs = sorted(values)
    n = len(xs)
    if n == 0:
        raise ValueError('percentile on empty list')
    if k <= 0:
        return xs[0]
    if k >= 1:
        return xs[-1]
    rank = 1 + (n - 1) * k
    m = int(math.floor(rank))
    d = rank - m
    # m is 1-indexed position
    if m <= 1:
        return xs[0] + d * (xs[1] - xs[0])
    if m >= n:
        return xs[-1]
    return xs[m-1] + d * (xs[m] - xs[m-1])


def fmt_number(v):
    if v is None:
        return ''
    # Normalize floats very close to integers
    if isinstance(v, (int,)):
        return str(v)
    if isinstance(v, float):
        if abs(v - round(v)) < 1e-12:
            return str(int(round(v)))
        return format(v, '.15g')
    # fall back
    return str(v)


def addr(col, row):
    return f'{col}{row}'


def build_cache_values():
    # Load with formulas present or not doesn't matter for reading source numbers.
    wb = load_workbook(IN_PATH, data_only=False)
    ts = wb[TASK_SHEET]
    ds = wb[DATA_SHEET]

    year_row = detect_year_header_row(ds)
    if year_row is None:
        raise RuntimeError('Could not detect year header row on Data sheet in H-L')

    years = [ds[f'{c}{year_row}'].value for c in COLS]

    # Build lookup dict from Data rows 21-38 (as specified)
    lookup = {}
    for r in range(21, 39):
        code = ds[f'D{r}'].value
        if code is None:
            continue
        for c, y in zip(COLS, years):
            val = ds[f'{c}{r}'].value
            lookup[(code, y)] = val

    # Read task years from Task row 10
    task_years = [ts[f'{c}10'].value for c in COLS]

    # Prepare caches
    caches = {}

    # Step 1 caches: lookups into H-L across the three blocks
    for (r1, r2) in LOOKUP_BLOCKS:
        for r in range(r1, r2+1):
            code = ts[f'D{r}'].value
            for c, y in zip(COLS, task_years):
                caches[addr(c, r)] = lookup.get((code, y))

    # Step 2 caches: gaps
    for i in range(6):
        r_success = 12 + i
        r_fail = 19 + i
        r_cap = 26 + i
        r_gap = 35 + i
        for c in COLS:
            s = caches[addr(c, r_success)]
            f = caches[addr(c, r_fail)]
            cap = caches[addr(c, r_cap)]
            if s is None or f is None or cap in (None, 0):
                gap = None
            else:
                gap = (s - f) / cap * 100
            caches[addr(c, r_gap)] = gap

    # Step 2b caches: stats (map by labels)
    stat_label_by_row = {r: ts[f'E{r}'].value for r in STATS_ROWS}

    def stat_value(label, col_letter):
        data = [caches[addr(col_letter, 35+i)] for i in range(6)]
        # Ensure all numeric
        if any(v is None for v in data):
            return None
        if label == 'Minimum':
            return min(data)
        if label == 'Maximum':
            return max(data)
        if label == 'Median':
            return statistics.median(data)
        if label == 'Simple mean':
            return statistics.fmean(data)
        if label == '25th percentile':
            return percentile_inc(data, 0.25)
        if label == '75th percentile':
            return percentile_inc(data, 0.75)
        raise KeyError(f'Unexpected stats label: {label!r}')

    for r in STATS_ROWS:
        label = stat_label_by_row[r]
        for c in COLS:
            caches[addr(c, r)] = stat_value(label, c)

    # Step 3 caches: weighted mean
    for c in COLS:
        gaps = [caches[addr(c, 35+i)] for i in range(6)]
        caps = [caches[addr(c, 26+i)] for i in range(6)]
        if any(v is None for v in gaps) or any(v is None for v in caps) or sum(caps) == 0:
            wm = None
        else:
            wm = sum(g*cap for g, cap in zip(gaps, caps)) / sum(caps)
        caches[addr(c, WEIGHTED_ROW)] = wm

    return caches, year_row


def write_formulas(year_header_row):
    wb = load_workbook(IN_PATH, data_only=False)
    ts = wb[TASK_SHEET]

    # Step 1 - lookup formulas
    # Note: year headers live in Data!H{year_header_row}:L{year_header_row}
    for (r1, r2) in LOOKUP_BLOCKS:
        for r in range(r1, r2+1):
            for c in COLS:
                formula = (
                    f"=INDEX(Data!$H$21:$L$38,"
                    f"MATCH($D{r},Data!$D$21:$D$38,0),"
                    f"MATCH({c}$10,Data!$H${year_header_row}:$L${year_header_row},0))"
                )
                ts[f'{c}{r}'].value = formula

    # Step 2 - net reliability gap
    for i in range(6):
        r_gap = 35 + i
        r_success = 12 + i
        r_fail = 19 + i
        r_cap = 26 + i
        for c in COLS:
            ts[f'{c}{r_gap}'].value = f"=({c}{r_success}-{c}{r_fail})/{c}{r_cap}*100"

    # Step 2b - summary stats (by label)
    label_to_formula = {
        'Minimum': 'MIN',
        'Maximum': 'MAX',
        'Median': 'MEDIAN',
        'Simple mean': 'AVERAGE',
        '25th percentile': 'PERCENTILE',
        '75th percentile': 'PERCENTILE',
    }

    for r in STATS_ROWS:
        label = ts[f'E{r}'].value
        if label not in label_to_formula:
            raise RuntimeError(f'Unexpected stats label in E{r}: {label!r}')
        func = label_to_formula[label]
        for c in COLS:
            rng = f"{c}35:{c}40"
            if label == '25th percentile':
                ts[f'{c}{r}'].value = f"={func}({rng},0.25)"
            elif label == '75th percentile':
                ts[f'{c}{r}'].value = f"={func}({rng},0.75)"
            else:
                ts[f'{c}{r}'].value = f"={func}({rng})"

    # Step 3 - weighted mean
    for c in COLS:
        ts[f'{c}{WEIGHTED_ROW}'].value = f"=SUMPRODUCT({c}35:{c}40,{c}26:{c}31)/SUM({c}26:{c}31)"

    wb.save(OUT_PATH)


def map_sheet_to_xml(zipf):
    # Read workbook.xml and relationships to find the XML filename for Task sheet
    wb_xml = zipf.read('xl/workbook.xml')
    rels_xml = zipf.read('xl/_rels/workbook.xml.rels')

    wb_root = etree.fromstring(wb_xml)
    rels_root = etree.fromstring(rels_xml)

    ns = {'m': NS_MAIN, 'r': NS_REL}

    sheet_id = None
    for sh in wb_root.xpath('.//m:sheets/m:sheet', namespaces=ns):
        if sh.get('name') == TASK_SHEET:
            sheet_id = sh.get(f'{{{NS_REL}}}id')
            break
    if sheet_id is None:
        raise RuntimeError('Could not find Task sheet in workbook.xml')

    target = None
    for rel in rels_root.xpath('.//r:Relationship', namespaces={'r': 'http://schemas.openxmlformats.org/package/2006/relationships'}):
        if rel.get('Id') == sheet_id:
            target = rel.get('Target')
            break
    if target is None:
        raise RuntimeError('Could not resolve Task sheet relationship target')

    # Target is relative to xl/ (often 'worksheets/sheet1.xml')
    if target.startswith('/'):
        target = target.lstrip('/')
    if not target.startswith('worksheets/'):
        # could be worksheets/sheet1.xml already; else still relative
        target = f'{target}'

    sheet_path = 'xl/' + target
    return sheet_path


def inject_cached_values(caches):
    # Modify Task sheet XML in the saved OUT_PATH zip
    tmp_path = OUT_PATH + '.tmp'

    with zipfile.ZipFile(OUT_PATH, 'r') as zin:
        sheet_path = map_sheet_to_xml(zin)
        sheet_xml = zin.read(sheet_path)

        root = etree.fromstring(sheet_xml)
        ns = {'m': NS_MAIN}

        def set_cell_value(cell_ref, number_value):
            c_el = root.xpath(f".//m:c[@r='{cell_ref}']", namespaces=ns)
            if not c_el:
                # If the cell element doesn't exist, create it under the right row.
                # This should be rare because Task sheet likely already has these cells.
                row_num = int(''.join(ch for ch in cell_ref if ch.isdigit()))
                row_el = root.xpath(f".//m:row[@r='{row_num}']", namespaces=ns)
                if not row_el:
                    sheetData = root.find(f'{{{NS_MAIN}}}sheetData')
                    row_el = etree.SubElement(sheetData, f'{{{NS_MAIN}}}row', r=str(row_num))
                else:
                    row_el = row_el[0]
                c_el = etree.SubElement(row_el, f'{{{NS_MAIN}}}c', r=cell_ref)
            else:
                c_el = c_el[0]

            # Ensure numeric type
            if 't' in c_el.attrib:
                c_el.attrib.pop('t', None)

            v_el = c_el.find(f'{{{NS_MAIN}}}v')
            if v_el is None:
                v_el = etree.SubElement(c_el, f'{{{NS_MAIN}}}v')
            v_el.text = fmt_number(number_value)

        # Only inject into our known target cells
        targets = set(caches.keys())
        for cell_ref in targets:
            set_cell_value(cell_ref, caches[cell_ref])

        new_sheet_xml = etree.tostring(root, xml_declaration=True, encoding='UTF-8', standalone=None)

        with zipfile.ZipFile(tmp_path, 'w', compression=zipfile.ZIP_DEFLATED) as zout:
            for item in zin.infolist():
                if item.filename == sheet_path:
                    zout.writestr(item, new_sheet_xml)
                else:
                    zout.writestr(item, zin.read(item.filename))

    os.replace(tmp_path, OUT_PATH)


def validate():
    wb_v = load_workbook(OUT_PATH, data_only=True)
    ts = wb_v[TASK_SHEET]

    def dump(range_str, label):
        print(f'-- {label} ({range_str}) --')
        for row in ts[range_str]:
            print([c.value for c in row])

    dump('H12:L17', 'data_only H12:L17')
    dump('H19:L24', 'data_only H19:L24')
    dump('H26:L31', 'data_only H26:L31')
    dump('H35:L40', 'data_only H35:L40')
    dump('H42:L47', 'data_only H42:L47')
    dump('H50:L50', 'data_only H50:L50')

    wb_f = load_workbook(OUT_PATH, data_only=False)
    tsf = wb_f[TASK_SHEET]
    print('-- formulas present? sample --')
    print('H12:', tsf['H12'].value)
    print('H35:', tsf['H35'].value)
    print('H42:', tsf['H42'].value)
    print('H50:', tsf['H50'].value)


# --- Execute ---
cache_vals, year_row = build_cache_values()
write_formulas(year_row)
# rebuild caches based on source; ok because formulas don't change source numbers
inject_cached_values(cache_vals)
validate()
